const touch = (id, x, y) => ({ pointerId: id, pointerType: "touch", x, y });
test("a second finger takes over node dragging and midpoint motion pans during a pinch", () => {
  const { view, commits } = makeView();
  view.downAt(touch(1, 100, 100));
  view.downAt(touch(2, 200, 100));
  view.moveAt(touch(1, 125, 150));
  view.moveAt(touch(2, 225, 150));
  assert.ok(Math.abs(view.transform.k - 1) < 1e-9);
  assert.ok(Math.abs(view.transform.x - 25) < 1e-8);
  assert.ok(Math.abs(view.transform.y - 50) < 1e-8);
  assert.equal(commits.length, 0);
  view.upAt(touch(2, 225, 150));
  view.moveAt(touch(1, 145, 160));
  assert.ok(Math.abs(view.transform.x - 45) < 1e-8);
  view.upAt(touch(1, 145, 160));
  view.dispose();
});
test("double-tap vertical zoom stays anchored and downward motion zooms in", () => {
  const { view } = makeView();
  view.downAt(touch(1, 600, 650));
  view.upAt(touch(1, 600, 650));
  view.downAt(touch(2, 600, 650));
  view.moveAt(touch(2, 600, 690));
  assert.ok(view.transform.k > 1);
  assert.ok(Math.abs(view.transform.x + 600 * view.transform.k - 600) < 1e-8);
  assert.ok(Math.abs(view.transform.y + 650 * view.transform.k - 650) < 1e-8);
  view.moveAt(touch(2, 600, 610));
  assert.ok(view.transform.k < 1);
  view.upAt(touch(2, 600, 610));
  view.dispose();
});
test("drag frames mutate indexed positions and commit graph state once on release", () => {
  const { view, commits, histories } = makeView();
  const e = (x, y) => ({ pointerId: 1, pointerType: "mouse", x, y });
  view.downAt(e(100, 100));
  for (let i = 1; i <= 100; i++) view.moveAt(e(100 + i, 100 + i));
  assert.equal(commits.length, 0);
  assert.equal(histories(), 1);
  assert.equal(view.scene.positions[0], 200);
  view.upAt(e(200, 200));
  assert.equal(commits.length, 1);
  assert.deepEqual(commits[0].get("urn:a"), { x: 200, y: 200 });
  assert.equal(commits[0].size, 1);
  view.dispose();
});

test("label hydration during a drag preserves the current pointer-driven coordinates", () => {
  const { view, props, commits } = makeView();
  const e = (x, y) => ({ pointerId: 1, pointerType: "mouse", x, y });
  view.downAt(e(100, 100));
  view.moveAt(e(140, 140));
  props.graph = {
    ...props.graph,
    nodes: props.graph.nodes.map((node) => ({
      ...node,
      label: "Updated " + node.label,
    })),
  };
  view.update();
  assert.equal(view.scene.positions[0], 140);
  assert.equal(view.scene.node(0).label, "Updated A");
  view.upAt(e(140, 140));
  assert.equal(commits[0].get("urn:a").x, 140);
  view.dispose();
});

test("the large canvas says when its nodes are still being arranged", () => {
  assert.equal(largeGraphHint(50000, true), "50,000 nodes · Arranging…");
  assert.equal(largeGraphHint(50000, false), "50,000 nodes · Zoom in or select a node for labels");
});
